import {renderMarkdown} from "./reports.js";
const css=document.createElement('style');css.textContent=`#artifacts-dialog{width:min(1120px,94vw);height:88vh;box-sizing:border-box;border:1px solid #d4d8cf;border-radius:18px;background:#faf6ed;color:#1c3338;padding:24px;overflow:hidden}#artifacts-dialog::backdrop{background:#172d3866;backdrop-filter:blur(4px)}#artifacts-dialog .artifact-top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}#artifacts-dialog h2{margin:0}#artifacts-dialog button,#artifacts-dialog a{color:inherit}#artifacts-dialog button{padding:9px 12px;border:1px solid #ccd2ca;background:#fffb;border-radius:8px;cursor:pointer}#artifacts-layout{display:grid;grid-template-columns:270px 1fr;gap:22px;height:calc(100% - 100px)}#artifacts-files,#artifacts-preview{overflow:auto;min-width:0}#artifacts-files button{display:block;width:100%;text-align:left;margin:6px 0;overflow-wrap:anywhere}#artifacts-files small{display:block;color:#667874;font-size:11px;margin-top:6px}#artifacts-files button[aria-current=true]{background:#dfe9d9}#artifacts-files h3{font-size:14px;margin:16px 0 6px}#artifacts-files p{font-size:12px;line-height:1.6;overflow-wrap:anywhere}#artifacts-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.8}#artifacts-preview img{max-width:100%;height:auto}#artifacts-preview iframe{width:100%;height:calc(100% - 80px);min-height:350px;border:1px solid #d4d8cf;background:white}#artifact-download{display:inline-block;padding:10px 0;text-decoration:underline}#artifacts-status{font-size:12px;line-height:1.6;color:#63756d}@media(max-width:650px){#artifacts-layout{grid-template-columns:1fr;grid-template-rows:180px 1fr}}`;document.head.append(css);
const dialog=document.createElement('dialog');dialog.id='artifacts-dialog';dialog.setAttribute('aria-label','交付成果');dialog.innerHTML='<div class="artifact-top"><h2 id="artifacts-title">交付成果</h2><div><button id="artifacts-refresh">刷新</button> <button id="artifacts-close">关闭</button></div></div><p id="artifacts-status" role="status"></p><div id="artifacts-layout"><section id="artifacts-files" aria-label="成果文件"></section><section id="artifacts-preview" aria-label="成果预览"></section></div>';document.body.append(dialog);
const $=s=>dialog.querySelector(s);let run=0,version=0,blobURL=null;
function clear(){if(blobURL){URL.revokeObjectURL(blobURL);blobURL=null;}$('#artifacts-preview').replaceChildren();}
const endpoint=(attempt,id)=>'/api/runs/'+run+'/artifacts/'+attempt+'/'+id;
async function preview(attempt,file){const token=++version;clear();for(const b of $('#artifacts-files').querySelectorAll('button'))b.setAttribute('aria-current',String(b.dataset.key===attempt+'/'+file.id));const box=$('#artifacts-preview'),title=document.createElement('h3'),link=document.createElement('a');title.textContent=file.name;link.id='artifact-download';link.textContent='下载原文件 · '+(file.size/1024).toFixed(1)+' KB';link.href=endpoint(attempt,file.id);link.download=file.name.split('/').pop();box.append(title,link);try{const r=await fetch(link.href);if(!r.ok)throw Error('成果快照读取失败，文件可能已丢失或被修改。');const data=await r.arrayBuffer();if(token!==version)return;const ext=file.name.split('.').pop().toLowerCase(),textTypes=['md','txt','json','csv','tsv','log','js','mjs','ts','tsx','jsx','css','xml','svg','yaml','yml','py','sh','sql','toml','ini','c','h','java','rs','go','vue','svelte'];const imageType={png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',avif:'image/avif'}[ext];if(imageType){blobURL=URL.createObjectURL(new Blob([data],{type:imageType}));const img=document.createElement('img');img.alt=file.name;img.src=blobURL;box.append(img);}else if(ext==='html'||ext==='htm'){const frame=document.createElement('iframe');frame.title='HTML 静态预览';frame.setAttribute('sandbox','');frame.referrerPolicy='no-referrer';frame.srcdoc='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'; font-src data:; form-action \'none\'; base-uri \'none\'">'+new TextDecoder().decode(data);const note=document.createElement('p');note.textContent='静态预览：脚本和外部资源不执行。';box.append(note,frame);}else if(ext==='pdf'){blobURL=URL.createObjectURL(new Blob([data],{type:'application/pdf'}));const frame=document.createElement('iframe');frame.title='PDF 预览';frame.src=blobURL;frame.setAttribute('sandbox','allow-same-origin');box.append(frame);}else if(textTypes.includes(ext)||!file.name.includes('.')){const pre=document.createElement('pre'),max=1024*1024;let text=new TextDecoder().decode(data.slice(0,max));if(ext==='json'&&data.byteLength<=max){try{text=JSON.stringify(JSON.parse(text),null,2);}catch{}}const displayed=text+(data.byteLength>max?'\n\n[预览仅显示前 1 MB，请下载完整文件]':'');if(ext==='md'){const article=document.createElement('article');article.style.cssText='font-size:14px;line-height:1.9;overflow-wrap:anywhere';renderMarkdown(displayed,article);box.append(article);}else{pre.textContent=displayed;box.append(pre);}}else{const p=document.createElement('p');p.textContent='此格式暂不支持网页预览，请下载后用对应应用打开。';box.append(p);}}catch(e){if(token===version){const p=document.createElement('p');p.textContent=e.message;box.append(p);}}}
async function load(){const token=++version;clear();$('#artifacts-files').replaceChildren();$('#artifacts-status').textContent='正在读取本轮成果…';try{const r=await fetch('/api/runs/'+run+'/artifacts');if(!r.ok)throw Error('成果列表读取失败，请刷新重试。');const data=await r.json();if(token!==version)return;let first=null,count=0;for(const attempt of data.attempts){const heading=document.createElement('h3');heading.textContent='执行批次 '+attempt.attempt+(attempt.outcome?' · '+({done:'完成',failed:'失败',cancelled:'已停止',nothing:'无事可做'}[attempt.outcome]||attempt.outcome):'');$('#artifacts-files').append(heading);for(const warning of attempt.warnings||[]){const p=document.createElement('p');p.textContent=warning;$('#artifacts-files').append(p);}if(attempt.status==='collecting'){const p=document.createElement('p');p.textContent='执行中，结束后收集文件。';$('#artifacts-files').append(p);}for(const file of attempt.files){count++;const b=document.createElement('button');b.dataset.key=attempt.attempt+'/'+file.id;b.textContent=file.name;const small=document.createElement('small');small.textContent=({created:'新文件',modified:'已修改',imported:'历史补录'}[file.change]||'文件')+' · '+(file.size/1024).toFixed(1)+' KB';b.append(small);b.onclick=()=>preview(attempt.attempt,file);$('#artifacts-files').append(b);first??={attempt:attempt.attempt,file};}}$('#artifacts-status').textContent=count?count+' 个文件快照 · 后续修改原文件不会改变本轮快照':data.attempts.length?(data.attempts.some(a=>a.status==='collecting')?'执行中，结束后收集文件，请稍后刷新。':'本轮未收集到文件，请查看左侧的收集说明。'):(data.collectorReady?'本轮尚无成果记录。历史任务不自动推断文件归属；新任务结束后收集工作目录内新增或修改的文件。':'自动收集等待中台重启后生效。此轮暂无已登记的成果文件。');if(first)preview(first.attempt,first.file);}catch(e){if(token===version)$('#artifacts-status').textContent=e.message;}}
export function openArtifacts(id){run=Number(id);$('#artifacts-title').textContent='第 '+run+' 轮 · 交付成果';if(!dialog.open)dialog.showModal();load();}
$('#artifacts-refresh').onclick=load;$('#artifacts-close').onclick=()=>dialog.close();dialog.onclose=()=>{version++;clear();};document.addEventListener('click',e=>{const button=e.target.closest('[data-artifacts-run]');if(button)openArtifacts(button.dataset.artifactsRun);});
